/// <summary>
/// CB871_CB872 Sales returns
/// Post delivery note posting multithread batch task
/// inspired from new class LedgerJournalBatchPost
/// </summary>
class METDeliveryNotePostingService extends METSysOperationService
{
    private guid topPickingProcessId;

}

Method.Source:
/// <summary>
/// Returns task service class name.
/// </summary>
/// <returns>Task service class name</returns>
protected str getTaskServiceClass()
{
    return classStr(METDeliveryNotePostingTaskService);
}

/// <summary>
/// Returns task service class method.
/// </summary>
/// <returns>Task service class method</returns>
protected str getTaskServiceClassMethod()
{
    return methodStr(METDeliveryNotePostingTaskService, process);
}

/// <summary>
/// Returns caption of the task service class.
/// </summary>
/// <returns>Task service class caption</returns>
protected str getTaskServiceCaption()
{
    return "@MET:ReturnOrderDeliveryNote";
}

/// <summary>
/// Executes the main process.
/// </summary>
/// <param name = "_contract">
/// <c>METSysOperationTaskDataContract</c>
/// </param>
public void process(METDeliveryNotePostingContract _contract)
{
    this.processInternal(_contract);
}

/// <summary>Initialise global variables</summary>
public void initialise()
{
    super();

    METDeliveryNotePostingContract contract = dataContract as METDeliveryNotePostingContract;
    Query query = contract.getQuery();

    this.processDeliveryNotesJournal(query);

}

/// <summary>
/// Initializes the task data contract.
/// </summary>
/// <param name = "_taskDataContract">task data contract</param>
protected void initTaskDataContract(METSysOperationTaskDataContract _taskDataContract)
{
    super(_taskDataContract);
    METDeliveryNotePostingContract contract = _taskDataContract as METDeliveryNotePostingContract;
    contract.parmTopPickingProcessId(topPickingProcessId);
}

/// <summary>
/// Provides task data contract.
/// </summary>
/// <returns>task data contract</returns>
protected METSysOperationTaskDataContract taskDataContractObject()
{
    return new METDeliveryNotePostingContract();
}

/// <summary>
/// Process return sales orders delivery notes from the query and insert RMA number in <c>METReturnOrderPostingQueue</c>
/// </summary>
/// <param name = "_query"><c>Query</c> object</param>
void processDeliveryNotesJournal(Query _query)
{
    #OCCRetryCount

    METReturnOrderPostingQueue::cleanUpPostReturnOrderProcessingQueue();
    RecordInsertList inventDeliveryNotePostingQueueList = new RecordInsertList(tableNum(METReturnOrderPostingQueue));


    QueryRun queryRun = new QueryRun(_query);

    while (queryRun.next())
    {
        try
        { 
            topPickingProcessId = newGuid();

            METReturnOrderDeliveryNoteHeader metRetrunOrderHeader = queryRun.get(tableNum(METReturnOrderDeliveryNoteHeader));

            this.addToDeliveryNotePostingQueueList(inventDeliveryNotePostingQueueList,
                                                        metRetrunOrderHeader.ReturnOrderNum);
        }
        catch (Exception::Deadlock)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::Deadlock;
            }
            else
            {
                retry;
            }
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
        catch (Exception::Error)
        {
            // catch the errors so processing can continue
            curext(); // avoids a warning about an empty block
        }
    }

    this.insertIntoTopPickingQueue(inventDeliveryNotePostingQueueList);
}

/// <summary>
/// Adding return sales order RMA number to process into the RecordInsertList
/// </summary>
/// <param name = "_deliveryNotePostQueueList"><c>RecordInsertList</c> object</param>
/// <param name = "_returnOrderNum">RMA number</param>
private void addToDeliveryNotePostingQueueList(RecordInsertList _deliveryNotePostQueueList, SalesReturnItemNum _returnOrderNum)
{
    METReturnOrderPostingQueue postRecord;
    postRecord.ProcessId = this.topPickingProcessId;
    postRecord.ReturnOrderNum = _returnOrderNum;

    _deliveryNotePostQueueList.add(postRecord);
}

/// <summary>
/// Buld insert from RecordInsertList into <c>METReturnOrderPostingQueue</c>
/// </summary>
/// <param name = "_deliveryNotePostQueueList">RecordInsertList to bulk insert</param>
private void insertIntoTopPickingQueue(RecordInsertList _deliveryNotePostQueueList)
{
    _deliveryNotePostQueueList.insertDatabase();
}
